Mesh<Point, double> mesh;

for (auto it = rt.finite_facets_begin(); it != rt.finite_facets_end(); ++it) {
    auto facet = *it;
    double area = rt.facet_area(facet);
    if (area < threshold) continue;

    for (int i = 0; i < 3; ++i) {
        auto neighbor = rt.facet_in_edge(facet, i);
        if (neighbor != rt.null_facet()) {
            Point dual_v1 = rt.dual(facet);
            Point dual_v2 = rt.dual(neighbor);
            mesh.add_edge(dual_v1, dual_v2);
        }
    }
    mesh.add_face_area(area);
}

return mesh;
// END_CODE

